$ErrorActionPreference='Stop'
$tmp=Join-Path $env:TEMP 'pc-iphone-scroll-m1.mjs'
try {
[System.IO.File]::WriteAllText($tmp,@'
setTimeout(()=>{console.log(JSON.stringify({error:'hard_timeout'}));process.exit(0)},5000);
try{const t=(await(await fetch('http://127.0.0.1:17447/json/list')).json()).find(x=>x.id==='507CA2A335B0F66B9544E22A8B264305');const w=new WebSocket(t.webSocketDebuggerUrl);
w.addEventListener('open',()=>w.send(JSON.stringify({id:2,method:'Runtime.evaluate',params:{expression:"(()=>{window.scrollTo(0,650);return {scrollY:window.scrollY,url:location.pathname,title:document.title}})()",returnByValue:true}})),{once:true});
w.addEventListener('message',e=>{let z=JSON.parse(e.data);if(z.id===2){console.log(JSON.stringify(z.result?.result?.value||{error:'no_result'}));process.exit(0)}})
}catch(e){console.log(JSON.stringify({error:String(e).slice(0,120)}));process.exit(0)}
'@,[System.Text.UTF8Encoding]::new($false))
& node.exe $tmp
} finally { Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue }
